mapper.sql:
WHERE f.deleted = 0

    AND f.status = #{q.status}


    AND f.category_id = #{q.categoryId}


    AND f.applicant_id = #{q.applicantId}


    AND (f.form_no LIKE CONCAT('%', #{q.keyword}, '%')
    OR f.reason LIKE CONCAT('%', #{q.keyword}, '%'))


    AND f.created_at >= #{q.dateFrom}


    AND f.created_at < DATE_ADD(#{q.dateTo}, INTERVAL 1 DAY)
